}

#[allow(clippy::borrowed_box)]
fn via_sized<S>(s: &Box<S>, visitor: &mut allocative::Visitor) {
    visitor
        .enter(
            allocative::Key::new("s"),
            std::mem::size_of_val(Box::as_ref(s)),
        )
        .exit()
}

